Repair the complete module below.

`BranchMetrics` receives synchronous providers. Each method calls only the providers it needs and returns `-1` if a provider throws or any consumed record is malformed. IDs and branch IDs must be integers; stock quantities, line quantities, and prices must be finite and nonnegative; order IDs must be unique; statuses must be one of the declared literals. `countDepleted` counts zero-quantity stock rows for the exact branch. `countQueued` counts queued orders for the exact branch. `sumSettledRevenue` totals `quantity * unitPrice` for lines belonging to settled orders in the exact branch; orphan lines are ignored. Empty valid inputs produce zero. Provider arrays must not be mutated.

Known-bad source:

```ts
export interface StockRow {
  readonly branchId: number;
  readonly quantity: number;
}
export type OrderStatus = "queued" | "settled" | "cancelled";
export interface OrderRow {
  readonly id: number;
  readonly branchId: number;
  readonly status: OrderStatus;
}
export interface LineRow {
  readonly orderId: number;
  readonly quantity: number;
  readonly unitPrice: number;
}
export class BranchMetrics {
  constructor(
    private readonly stocks: () => readonly StockRow[],
    private readonly orders: () => readonly OrderRow[],
    private readonly lines: () => readonly LineRow[],
  ) {}

  countDepleted(branchId: number): number {
    try {
      const rows = this.stocks();
      if (!Number.isInteger(branchId) || !rows.every(validStock)) return -1;
      return rows.filter((row) => row.branchId === branchId && row.quantity === 0).length;
    } catch {
      return -1;
    }
  }

  countQueued(branchId: number): number {
    try {
      const rows = this.orders();
      if (!Number.isInteger(branchId) || !validOrders(rows)) return -1;
      return rows.filter((row) => row.branchId === branchId && row.status === "queued").length;
    } catch {
      return -1;
    }
  }

  sumSettledRevenue(branchId: number): number {
    try {
      const orders = this.orders();
      const lines = this.lines();
      if (!Number.isInteger(branchId) || !validOrders(orders) || !lines.every(validLine)) return -1;
      const settled = new Set(
        orders.filter((order) => order.branchId === branchId && order.status !== "settled")
          .map((order) => order.id),
      );
      return lines.reduce(
        (sum, line) => settled.has(line.orderId) ? sum + line.quantity * line.unitPrice : sum,
        0,
      );
    } catch {
      return -1;
    }
  }
}

function validStock(row: StockRow): boolean {
  return Number.isInteger(row.branchId) && Number.isFinite(row.quantity) && row.quantity >= 0;
}
function validLine(row: LineRow): boolean {
  return Number.isInteger(row.orderId) && Number.isFinite(row.quantity) && row.quantity >= 0
    && Number.isFinite(row.unitPrice) && row.unitPrice >= 0;
}
function validOrders(rows: readonly OrderRow[]): boolean {
  const ids = new Set<number>();
  return rows.every((row) => {
    const valid = Number.isInteger(row.id) && Number.isInteger(row.branchId)
      && (row.status === "queued" || row.status === "settled" || row.status === "cancelled")
      && !ids.has(row.id);
    ids.add(row.id);
    return valid;
  });
}
