import { BranchMetrics, type LineRow, type OrderRow, type StockRow } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const stocks: StockRow[] = [
  { branchId: 1, quantity: 0 },
  { branchId: 1, quantity: 3 },
  { branchId: 2, quantity: 0 },
  { branchId: -4, quantity: 0 },
];
const orders: OrderRow[] = [
  { id: 10, branchId: 1, status: 'settled' },
  { id: 11, branchId: 1, status: 'queued' },
  { id: 12, branchId: 1, status: 'cancelled' },
  { id: 13, branchId: 2, status: 'settled' },
];
const lines: LineRow[] = [
  { orderId: 10, quantity: 2, unitPrice: 3 },
  { orderId: 10, quantity: 1.5, unitPrice: 4 },
  { orderId: 11, quantity: 10, unitPrice: 10 },
  { orderId: 13, quantity: 5, unitPrice: 2 },
  { orderId: 999, quantity: 100, unitPrice: 100 },
];
const beforeStocks = JSON.stringify(stocks);
const beforeOrders = JSON.stringify(orders);
const beforeLines = JSON.stringify(lines);
const metrics = new BranchMetrics(() => stocks, () => orders, () => lines);
equal(metrics.countDepleted(1), 1, 'counts depleted stock for exact branch');
equal(metrics.countDepleted(-4), 1, 'integer branch IDs may be negative');
equal(metrics.countQueued(1), 1, 'counts queued orders for exact branch');
equal(metrics.sumSettledRevenue(1), 12, 'sums only settled exact-branch revenue');
equal(metrics.sumSettledRevenue(2), 10, 'selects another branch');
equal(JSON.stringify(stocks), beforeStocks, 'does not mutate stocks');
equal(JSON.stringify(orders), beforeOrders, 'does not mutate orders');
equal(JSON.stringify(lines), beforeLines, 'does not mutate lines');

const empty = new BranchMetrics(() => [], () => [], () => []);
equal(empty.countDepleted(1), 0, 'empty stocks produce zero');
equal(empty.countQueued(1), 0, 'empty orders produce zero');
equal(empty.sumSettledRevenue(1), 0, 'empty revenue inputs produce zero');

let stockCalls = 0;
let orderCalls = 0;
let lineCalls = 0;
const selective = new BranchMetrics(
  () => { stockCalls++; return []; },
  () => { orderCalls++; return []; },
  () => { lineCalls++; return []; },
);
selective.countDepleted(1);
equal(stockCalls, 1, 'countDepleted calls stocks');
equal(orderCalls, 0, 'countDepleted does not call orders');
equal(lineCalls, 0, 'countDepleted does not call lines');
selective.countQueued(1);
equal(stockCalls, 1, 'countQueued does not call stocks');
equal(orderCalls, 1, 'countQueued calls orders');
equal(lineCalls, 0, 'countQueued does not call lines');
selective.sumSettledRevenue(1);
equal(stockCalls, 1, 'revenue does not call stocks');
equal(orderCalls, 2, 'revenue calls orders');
equal(lineCalls, 1, 'revenue calls lines');

const throwing = new BranchMetrics(
  () => { throw new Error('stock'); },
  () => { throw new Error('order'); },
  () => { throw new Error('line'); },
);
equal(throwing.countDepleted(1), -1, 'handles stock provider failure');
equal(throwing.countQueued(1), -1, 'handles order provider failure');
equal(throwing.sumSettledRevenue(1), -1, 'handles consumed provider failure');

equal(metrics.countDepleted(1.5), -1, 'rejects non-integer branch argument');
equal(metrics.countQueued(Number.NaN), -1, 'rejects NaN branch argument');
equal(metrics.sumSettledRevenue(Number.POSITIVE_INFINITY), -1, 'rejects infinite branch argument');

const malformedStocks: readonly StockRow[][] = [
  [{ branchId: 1.5, quantity: 0 }],
  [{ branchId: 1, quantity: -1 }],
  [{ branchId: 1, quantity: Number.NaN }],
  [{ branchId: 1, quantity: Number.POSITIVE_INFINITY }],
];
for (const rows of malformedStocks) {
  equal(new BranchMetrics(() => rows, () => [], () => []).countDepleted(1), -1, 'rejects malformed stock');
}

const malformedOrders: readonly OrderRow[][] = [
  [{ id: 1.5, branchId: 1, status: 'queued' }],
  [{ id: 1, branchId: 1.5, status: 'queued' }],
  [{ id: 1, branchId: 1, status: 'other' } as unknown as OrderRow],
  [{ id: 1, branchId: 1, status: 'queued' }, { id: 1, branchId: 2, status: 'settled' }],
];
for (const rows of malformedOrders) {
  const subject = new BranchMetrics(() => [], () => rows, () => []);
  equal(subject.countQueued(1), -1, 'queued rejects malformed orders');
  equal(subject.sumSettledRevenue(1), -1, 'revenue rejects malformed orders');
}

const malformedLines: readonly LineRow[][] = [
  [{ orderId: 1.5, quantity: 1, unitPrice: 1 }],
  [{ orderId: 1, quantity: -1, unitPrice: 1 }],
  [{ orderId: 1, quantity: 1, unitPrice: -1 }],
  [{ orderId: 1, quantity: Number.NaN, unitPrice: 1 }],
  [{ orderId: 1, quantity: 1, unitPrice: Number.POSITIVE_INFINITY }],
];
for (const rows of malformedLines) {
  equal(new BranchMetrics(() => [], () => [], () => rows).sumSettledRevenue(1), -1, 'rejects malformed lines');
}

